void centroid_decomposition(int n, vector<vector<int>>& g) {
    int root = 0;                   // 重心
    int now_n = n;                  // 当前块大小
    var siz = vector<int>(n + 1);   // 以本轮 DFS 起点为根的子树大小
    var mxsiz = vector<int>(n + 1); // 每个子树大小的最大值
    var vis = vector<bool>(n + 1);  // 已经当过重心的点
    mxsiz[0] = 1e9;                 // 哨兵

    var getroot = [&](var getroot, int now, int fa)->void {
        siz[now] = 1; mxsiz[now] = 0;
        for (int to : g[now]) {
            if (to == fa or vis[to])continue;
            getroot(getroot, to, now);
            siz[now] += siz[to];
            mxsiz[now] = max(mxsiz[now], siz[to]);
        }
        mxsiz[now] = max(mxsiz[now], now_n - siz[now]); // 父亲方向那一块
        if (mxsiz[now] < mxsiz[root])root = now;
        };

    var cal = [&](int now)->void {
        // 题目相关：处理"和重心 now 有关的东西"
        };

    var dfs = [&](var dfs, int now)->void {
        int tot = now_n;    // 本块大小（进循环后 now_n 会被覆盖）
        vis[now] = 1;
        cal(now);
        for (int to : g[now]) {
            if (vis[to])continue;
            // to 那块的"真实大小"：siz[to] > siz[now] 说明 to 是父亲方向
            now_n = (siz[to] > siz[now]) ? tot - siz[now] : siz[to];
            root = 0; mxsiz[0] = 1e9;
            getroot(getroot, to, now);
            dfs(dfs, root);
        }
        };

    getroot(getroot, 1, 0);
    dfs(dfs, root);
}
